import { readFileSync } from "node:fs";

const timings = JSON.parse(readFileSync("timings.json", "utf8"));
const shards = Array.from({ length: SHARDS }, () => ({ total: 0, files: [] }));

for (const [file, ms] of Object.entries(timings).sort((a, b) => b[1] - a[1])) {
  const lightest = shards.reduce((a, b) => (a.total <= b.total ? a : b));
  lightest.files.push(file);
  lightest.total += ms;
}
